import { collection, getDocs } from 'firebase/firestore';
import { db } from '@/firebase';
import PoemPostClient from './PoemPostClient';

// Required for output: 'export' — tells Next.js to only render
// pre-known slugs and skip any unknown ones at build time.
export const dynamicParams = false;

export async function generateStaticParams() {
  try {
    const snapshot = await getDocs(collection(db, 'poems'));
    const params = snapshot.docs
      .map((doc) => ({ slug: doc.data().slug }))
      .filter((p) => !!p.slug); // exclude docs without a slug field
    // Always return at least one placeholder so the route is registered
    return params.length > 0 ? params : [{ slug: '_placeholder' }];
  } catch (error) {
    console.error('Error generating static params for poems:', error);
    // Return placeholder so the route is still registered in the build
    return [{ slug: '_placeholder' }];
  }
}

export default function Page() {
  return <PoemPostClient />;
}
